<title>Afterimage Camera Club</title>
<style>
@font-face{font-family:Club;src:url('data:font/ttf;base64,') format('truetype');font-weight:700;font-display:swap}
:root{--paper:#c7e7ee;--ink:#102e49;--white:#f6fbff;--yellow:#ffcf62;--muted:#34566d}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}::selection{background:var(--yellow);color:var(--ink)}html{scrollbar-color:var(--ink) var(--paper)}a{color:inherit;text-underline-offset:4px}button,input,select{font:inherit;accent-color:var(--ink)}button,select{min-height:46px;border:1px solid var(--ink);border-radius:8px;background:transparent;color:var(--ink);padding:9px 14px}button{cursor:pointer}button:hover{background:#afd7e1}button:disabled{opacity:.55;cursor:wait}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #98510b;outline-offset:4px}a:hover{color:#264e69}button[aria-pressed=true]{background:var(--ink);color:var(--white)}main{max-width:1280px;margin:auto;padding:22px 38px 50px}nav{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:24px}nav a{display:inline-flex;align-items:center;min-height:44px}nav span{font-size:.85rem;color:var(--muted)}h1,h2,h3{font-family:Club,system-ui,sans-serif;line-height:1.02;text-wrap:balance}h1{font-size:clamp(2.6rem,6.6vw,5.7rem);letter-spacing:-.035em;margin:0 0 14px;max-width:950px}header p{max-width:65ch;font-size:1.1rem;margin:0 0 28px;color:var(--muted)}.studio{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:32px;align-items:start}.mount{margin:0;background:var(--white);padding:12px 12px 0;box-shadow:0 12px 28px #102e4920}.frame{position:relative;background:var(--ink);aspect-ratio:3/2;overflow:hidden}canvas{width:100%;height:100%;display:block}.live-label{position:absolute;left:12px;top:12px;padding:4px 8px;background:var(--white);color:var(--ink);font-size:.75rem;font-weight:700;pointer-events:none}.mount figcaption{display:flex;justify-content:space-between;gap:12px;padding:14px 4px 17px;font-size:.85rem}.caption-name{font-weight:700}.exposure{font-variant-numeric:tabular-nums}.controls h2{font-size:1.6rem;margin:0 0 22px}.field{margin:0 0 23px}.field label,.field legend{font-weight:700;display:block;margin-bottom:8px}.field small{display:block;color:var(--muted);margin-top:7px}.field select{width:100%;background:var(--white)}.field input[type=range]{width:100%;min-height:44px;margin:0}.range-labels{display:flex;justify-content:space-between;font-size:.8rem;color:var(--muted)}output{font-variant-numeric:tabular-nums}.shutter{width:100%;font-weight:700;background:var(--yellow);border:0;min-height:55px}.shutter:hover{background:#f3bb3d}.secondary{display:flex;gap:10px;margin-top:12px}.secondary button{flex:1;font-size:.88rem}.status{font-size:.9rem;min-height:3em;color:var(--muted);margin:14px 0 0}.assignment{margin-top:34px;padding-top:23px;border-top:1px solid #799eae}.assignment h2{font-size:1.8rem;margin:0 0 10px}.assignment p{margin:0 0 12px;max-width:65ch}.taskline{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.taskline span{font-size:.9rem}.taskline button{font-weight:600}.roll{margin-top:35px}.roll h2{font-size:1.8rem;margin:0 0 8px}.roll p{color:var(--muted);margin:0 0 16px}.prints{display:flex;gap:16px;align-items:start;overflow-x:auto;padding:4px 4px 20px}.prints:empty{display:none}.print{flex:0 0 190px;background:var(--white);padding:8px;border:0;border-radius:0;text-align:left;box-shadow:0 6px 12px #102e4915}.print:hover{background:#eaf5fc}.print[aria-pressed=true]{background:var(--white);color:var(--ink);outline:3px solid var(--ink);outline-offset:0}.print img{display:block;width:100%;aspect-ratio:3/2}.print span{display:block;padding:9px 2px 3px;font-size:.8rem}.about{margin-top:38px;display:grid;grid-template-columns:1fr 1fr;gap:40px;border-top:1px solid #799eae;padding-top:26px}.about h2{font-size:1.5rem;margin:0 0 12px}.about p{margin:0 0 12px;color:var(--muted);max-width:65ch}footer{margin-top:32px;font-size:.9rem;color:var(--muted)}.error{padding:20px;background:var(--white);color:var(--ink)}[hidden]{display:none!important}
@media(max-width:760px){main{padding:14px 18px 35px}nav{margin-bottom:18px}nav span{max-width:130px;text-align:right}.studio{display:flex;flex-direction:column;gap:25px}.studio>div{display:contents}.studio .mount{order:0;width:100%}.studio .controls{order:1;width:100%}.studio .assignment{order:2;margin-top:0;width:100%}.controls h2{margin-bottom:15px}.controls-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.field{min-width:0;margin-bottom:17px}.field:first-child{grid-column:1/-1}.about{grid-template-columns:1fr;gap:22px}.mount{padding:8px 8px 0}.mount figcaption{font-size:.78rem}h1{font-size:clamp(2.5rem,11vw,4.5rem)}header p{font-size:1rem;margin-bottom:20px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
</head>
<body>
<main>
<nav><a href="./">Back to Chloe Reads Jon</a><span>No camera required.</span></nav>
<header><h1>Afterimage<br>Camera Club</h1><p>A shutter is a little door for time. Leave it open and a moving light becomes a drawing. Make a photograph of a moment, or a whole journey.</p></header>
<div class="studio">
<div>
<figure class="mount">
<div class="frame"><canvas id="scene" width="1200" height="800" role="img" aria-label="Illustrated lake at blue hour, with a simulated moving light and its exposure trail."></canvas><span class="live-label" id="viewLabel">LIVE PREVIEW</span></div>
<figcaption><span class="caption-name" id="caption">Lantern loop · blue hour</span><span class="exposure" id="exposureText">2 s exposure</span></figcaption>
</figure>
<p class="error" id="error" hidden>The lake illustration could not load. Reload this page to try again.</p>
<section class="assignment" aria-labelledby="assignmentTitle">
<h2 id="assignmentTitle">Your first assignment</h2>
<p id="taskText">Freeze the wandering light into a tiny dot. Choose a shutter of 1/30 s or faster, then take a photo.</p>
<div class="taskline"><span id="taskProgress">Assignment 1 of 3</span><button id="hint">Show a hint</button><button id="next" hidden>Next assignment</button><button id="restart" hidden>Try the assignments again</button></div>
<p id="hintText" hidden></p>
</section>
</div>
<section class="controls" aria-labelledby="settingsTitle">
<h2 id="settingsTitle">Make your exposure</h2>
<div class="controls-grid">
<div class="field"><label for="duration">Shutter duration <output id="durationOut">2 s</output></label><input id="duration" aria-valuetext="2 seconds" aria-describedby="durationNote" type="range" min="0" max="7" step="1" value="6"><div class="range-labels"><span>Freeze a moment</span><span>Draw a journey</span></div><small id="durationNote">A longer shutter gathers a longer trail.</small></div>
<div class="field"><label for="path">Light's journey</label><select id="path"><option value="loop">Lantern loop</option><option value="spiral">Spiral dance</option><option value="sweep">Lakeside sweep</option></select></div>
<div class="field"><label for="colour">Light colour</label><select id="colour"><option value="gold">Honey gold</option><option value="mint">Glacier mint</option><option value="pink">Rose pink</option></select></div>
<div class="field"><label for="phase">Start along the path</label><input id="phase" type="range" min="0" max="100" value="0"><small>Move the light before opening the shutter.</small></div>
</div>
<button class="shutter" id="capture" disabled>Loading the lake…</button>
<div class="secondary"><button id="motion" aria-pressed="false">Play the light</button><button id="download" disabled>Save photo</button></div>
<p class="status" id="status" role="status" aria-live="polite">Try 1/125 s, then 8 s. Same light. Very different photograph.</p>
</section>
</div>
<section class="roll" aria-labelledby="rollTitle"><h2 id="rollTitle">Your contact sheet</h2><p id="empty">Your last six photos will appear here. Tap a print to compare it with another.</p><div class="prints" id="prints" aria-label="Captured photographs"></div><button id="return" hidden>Return to live preview</button></section>
<section class="about">
<div><h2>What the shutter is doing</h2><p>At 1/125 second, the light barely has time to move. At 8 seconds, it finishes its entire route. Each trail here is drawn from the positions the light visits while the shutter is open.</p><p>Try a short exposure in one colour, then a long one in another. You can save any selected print as a PNG.</p></div>
<div><h2>A camera for Mom</h2><p>In 2004, Jon wrote about buying his mom a Canon A75 digital camera. She was thrilled. This little club keeps that feeling of finding out what a camera can do.</p><p>Inspired by Jon's <a href="?source=1">“Hi Vic”</a>.</p><p><small>An illustrated shutter-time simulation, not an A75 emulator. Brightness is held steady to make the trails easy to compare; aperture, ISO, sensor noise and camera shake are not modelled. Original lake artwork generated for this page.</small></p></div>
</section>
<footer>Made for Jon &amp; Nathan. Photos stay in this tab unless you save them.</footer>
<noscript><p class="error">This camera club needs JavaScript for its light trails and shutter controls.</p></noscript>
</main>
<script>
'use strict';
const $=id=>document.getElementById(id);
const canvas=$('scene'),ctx=canvas.getContext('2d');
const lake=new Image();lake.src='data:image/webp;base64,';
const times=[1/125,1/60,1/30,1/8,1/2,1,2,8],labels=['1/125 s','1/60 s','1/30 s','1/8 s','1/2 s','1 s','2 s','8 s'];
const pathNames={loop:'Lantern loop',spiral:'Spiral dance',sweep:'Lakeside sweep'};
const colours={gold:'#ffda7a',mint:'#8effdf',pink:'#ffa2d4'};
let ready=false,playing=false,raf=0,last=0,phase=0,selected=null,photos=[],serial=0,task=0,done=[false,false,false];
const tasks=[
{title:'Your first assignment',text:'Freeze the wandering light into a tiny dot. Choose a shutter of 1/30 s or faster, then take a photo.',hint:'Move the shutter slider all the way left to 1/125 s.',test:p=>p.duration<=1/30},
{title:'Catch a ribbon of light',text:'Catch a visible trail without completing the whole route. Use a shutter from 1/2 s to 2 s, then take a photo.',hint:'Try 1 s. The light travels partway along its route while the shutter is open.',test:p=>p.duration>=.5&&p.duration<=2},
{title:'Close the lantern loop',text:'Choose Lantern loop and leave the shutter open for a full 8 seconds. Take a photo of the complete figure-eight.',hint:'Choose Lantern loop, then move the shutter slider all the way right.',test:p=>p.duration===8&&p.path==='loop'}
];
function point(t,path){
 const a=t/8*Math.PI*2;
 if(path==='spiral'){const r=.06+.16*(.5+.5*Math.sin(a));return [600+Math.cos(a*3)*1200*r,370+Math.sin(a*3)*800*r];}
 if(path==='sweep')return [600+380*Math.cos(a),460+65*Math.sin(a)];
 return [600+330*Math.sin(a),330+120*Math.sin(2*a)];
}
function settings(){return {duration:times[+$('duration').value],label:labels[+$('duration').value],path:$('path').value,colour:$('colour').value,phase};}
function draw(p){
 if(!ready)return;
 ctx.drawImage(lake,0,0,1200,800);
 const n=Math.max(2,Math.ceil(p.duration*120)),start=p.phase*8;
 ctx.strokeStyle=colours[p.colour];ctx.lineWidth=5;ctx.lineCap='round';ctx.lineJoin='round';
 ctx.beginPath();
 for(let i=0;i<=n;i++){const [x,y]=point(start+i/n*p.duration,p.path);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}
 ctx.stroke();
 const [x,y]=point(start+p.duration,p.path);
 ctx.fillStyle='#fff8e6';ctx.beginPath();ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();
 $('caption').textContent=pathNames[p.path]+' · blue hour';
 $('exposureText').textContent=p.label+' exposure';
 canvas.setAttribute('aria-label',pathNames[p.path]+', '+p.label+' exposure in '+p.colour+'. '+(p.duration<.04?'A tiny frozen dot.':p.duration===8?'A complete luminous route.':'A partial light trail.'));
}
function preview(){
 selected=null;
 $('return').hidden=true;$('viewLabel').textContent='LIVE PREVIEW';
 document.querySelectorAll('.print').forEach(b=>b.setAttribute('aria-pressed','false'));
 $('download').disabled=true;
 $('durationOut').value=labels[+$('duration').value];
 $('duration').setAttribute('aria-valuetext',labels[+$('duration').value].replace(' s',' seconds'));
 const d=times[+$('duration').value];
 $('durationNote').textContent=d<.04?'A quick shutter freezes the moving light.':d===8?'Eight seconds gathers the complete route.':'A longer shutter gathers a longer trail.';
 draw(settings());
}
function stop(){playing=false;cancelAnimationFrame(raf);$('motion').textContent='Play the light';$('motion').setAttribute('aria-pressed','false');}
function animate(now){
 if(!playing)return;
 if(last)phase=(phase+Math.min(now-last,50)/8000)%1;
 last=now;$('phase').value=Math.round(phase*100);draw(settings());raf=requestAnimationFrame(animate);
}
function setTask(){
 $('assignmentTitle').textContent=tasks[task].title;$('taskText').textContent=tasks[task].text;
 $('taskProgress').textContent='Assignment '+(task+1)+' of 3'+(done[task]?' · complete':'');
 $('hintText').hidden=true;$('hint').hidden=done[task];$('next').hidden=!done[task]||task===2;$('restart').hidden=!done[task]||task!==2;
}
function selectPhoto(p){
 stop();selected=p;$('viewLabel').textContent='PRINT '+p.id;$('return').hidden=false;$('download').disabled=false;
 document.querySelectorAll('.print').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.id===p.id)));
 draw(p);$('status').textContent='Viewing photo '+p.id+'. '+pathNames[p.path]+', '+p.label+'. Save it, or change a setting for a new exposure.';
}
function capture(){
 if(!ready)return;
 stop();const p={...settings(),id:++serial};draw(p);p.url=canvas.toDataURL('image/png');photos.push(p);if(photos.length>6)photos.shift();
 const button=document.createElement('button');button.className='print';button.dataset.id=p.id;button.setAttribute('aria-pressed','false');
 const img=document.createElement('img');img.src=p.url;img.alt='';const text=document.createElement('span');text.textContent='Photo '+p.id+' · '+p.label+' · '+pathNames[p.path];button.append(img,text);button.addEventListener('click',()=>selectPhoto(p));
 $('prints').append(button);if($('prints').children.length>6)$('prints').firstElementChild.remove();
 $('empty').textContent='Tap a print to view it. Your latest six photos stay here until you close this tab.';
 selectPhoto(p);
 if(!done[task]){
 if(tasks[task].test(p)){done[task]=true;setTask();$('status').textContent=task===2?'All three assignments complete! You caught a moment, a ribbon and a whole journey. Keep experimenting.':'Assignment complete! Your photo caught exactly what you were looking for.';}
 else $('status').textContent='Photo '+p.id+' saved to your contact sheet. For this assignment: '+tasks[task].text;
 }
}
['duration','path','colour'].forEach(id=>$(id).addEventListener('input',()=>{stop();preview();}));
$('phase').addEventListener('input',()=>{stop();phase=+$('phase').value/100;preview();});
$('capture').addEventListener('click',capture);
$('motion').addEventListener('click',()=>{
 if(playing){stop();return;}
 preview();playing=true;last=0;$('motion').textContent='Pause the light';$('motion').setAttribute('aria-pressed','true');raf=requestAnimationFrame(animate);
});
$('return').addEventListener('click',preview);
$('hint').addEventListener('click',()=>{$('hintText').textContent=tasks[task].hint;$('hintText').hidden=!$('hintText').hidden;});
$('next').addEventListener('click',()=>{task++;setTask();$('hint').focus();});
$('restart').addEventListener('click',()=>{task=0;done=[false,false,false];setTask();$('hint').focus();$('status').textContent='Assignments reset. Your photos are still on the contact sheet.';});
$('download').addEventListener('click',()=>{
 if(!selected)return;const a=document.createElement('a');a.download='afterimage-photo-'+selected.id+'.png';a.href=selected.url;a.click();$('status').textContent='Photo '+selected.id+' is ready to save as a PNG.';
});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
lake.onload=()=>{ready=true;$('capture').disabled=false;$('capture').textContent='Take a photo';preview();};
lake.onerror=()=>{$('error').hidden=false;$('capture').textContent='Lake unavailable';$('motion').disabled=true;};
</script>
</body></html>
